const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s)), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), money=n=>'$'+Math.round(n).toLocaleString('en-US'), uid=()=>crypto.randomUUID();
