let S={schema:2,name:'My little outside',width:30,depth:20,shape:'curve',points:[{x:0,y:0},{x:1,y:0},{x:1,y:1},{x:0,y:1}],curve:.12,material:'clay',step:0,items:[{id:'olive-start',kind:'olive',x:.16,y:.23,w:5,h:5,angle:0},{id:'flowers-start',kind:'flowers',x:.16,y:.73,w:4,h:2,angle:0},{id:'table-start',kind:'table',x:.65,y:.55,w:4,h:4,angle:0},{id:'lamp-start',kind:'light',x:.88,y:.78,w:.6,h:.6,angle:0}],zones:[{id:'soil-start',name:'Planting bed',points:[{x:0,y:0},{x:.31,y:0},{x:.29,y:1},{x:0,y:1}]}],routes:[],night:false,lights:true,season:'summer',target:8000,reserve:10,tasks:[false,false,false],version:1};
