function renderAll(controls=false){$('#project-name').value=S.name;$('#day').classList.toggle('active',!S.night);$('#night').classList.toggle('active',S.night);$('#season').value=S.season;$('#lights').checked=S.lights;renderSteps();if(controls)renderControls();renderCanvas();renderInspector();renderPricing();$('#undo').disabled=!undoStack.length;$('#redo').disabled=!redoStack.length;$('#render-time').value=S.night?'night':'day';$('#render-season').value=S.season;$('#render-lights').checked=S.lights;if(location.hash==='#visuals')renderPerspective()}
function toNorm(e){const svg=$('#garden'),pt=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse()),b=bounds();return{x:clamp((pt.x-b.x)/b.w,0,1),y:clamp((pt.y-b.y)/b.h,0,1)}}
$('#garden').addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=toNorm(e);if(tool==='soil'||tool==='route'){if(draft.length>=50){notify('Finish this shape before adding more points.');return}draft.push(p);renderCanvas();renderControls();return}const it=e.target.closest('[data-item-id]'),v=e.target.closest('[data-vertex-id]'),zv=e.target.closest('[data-zone-vertex]'),zone=e.target.closest('[data-zone-id]'),route=e.target.closest('[data-route-id]');if(v){drag={type:'boundary',index:+v.dataset.vertexId,start:p,before:clone(S)};selection=null}else if(zv&&selection?.type==='zone'){drag={type:'zone',id:selection.id,index:+zv.dataset.zoneVertex,start:p,before:clone(S)}}else if(it){selection={type:'item',id:it.dataset.itemId};const o=S.items.find(i=>i.id===selection.id);drag={type:'item',id:o.id,start:p,x:o.x,y:o.y,before:clone(S)}}else if(route){selection={type:'route',id:route.dataset.routeId}}else if(zone&&S.step===1){selection={type:'zone',id:zone.dataset.zoneId}}else selection=null;if(drag){$('#garden').setPointerCapture(e.pointerId);e.preventDefault()}renderCanvas();renderInspector()});
$('#garden').addEventListener('pointermove',e=>{if(!drag)return;const p=toNorm(e);if(drag.type==='boundary'){let pts=clone(S.points);pts[drag.index]={...pts[drag.index],...p};if(simplePolygon(pts))S.points=pts}else if(drag.type==='item'){const i=S.items.find(i=>i.id===drag.id);i.x=clamp(drag.x+p.x-drag.start.x,0,1);i.y=clamp(drag.y+p.y-drag.start.y,0,1)}else if(drag.type==='zone'){const z=S.zones.find(z=>z.id===drag.id),pts=clone(z.points);pts[drag.index]=p;if(simplePolygon(pts))z.points=pts}renderCanvas()});
function finishDrag(){if(!drag)return;if(JSON.stringify(S)!==JSON.stringify(drag.before)){undoStack.push(drag.before);redoStack=[];S.version++;scheduleSave()}drag=null;renderAll(true)}$('#garden').addEventListener('pointerup',finishDrag);$('#garden').addEventListener('pointercancel',finishDrag);$('#garden').addEventListener('keydown',e=>{const n=e.target.closest('[data-item-id]');if(!n)return;if(e.key==='Enter'||e.key===' '){selection={type:'item',id:n.dataset.itemId};renderInspector();renderCanvas();e.preventDefault()}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const id=n.dataset.itemId;change(()=>{const i=S.items.find(i=>i.id===id);if(e.key==='ArrowLeft')i.x=clamp(i.x-.5/S.width,0,1);if(e.key==='ArrowRight')i.x=clamp(i.x+.5/S.width,0,1);if(e.key==='ArrowUp')i.y=clamp(i.y-.5/S.depth,0,1);if(e.key==='ArrowDown')i.y=clamp(i.y+.5/S.depth,0,1);selection={type:'item',id}});$(`[data-item-id="${id}"]`)?.focus()}});
function renderPerspective(){const b=bounds(),d=pathFor(vertices(),b,S.shape==='curve'),night=S.night,sky=night?'#253943':'#e6d9bc',hill=night?'#344d48':S.season==='autumn'?'#b3a476':'#adb88c',a=.86,bb=-.12,c=.38,dd=.48,e=500-a*425-c*310,f=420-bb*425-dd*310,mat=`matrix(${a} ${bb} ${c} ${dd} ${e} ${f})`,project=p=>{const q=xy(p,b);return{x:a*q.x+c*q.y+e,y:bb*q.x+dd*q.y+f}};let html=patterns()+`<defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="${sky}"/><stop offset="1" stop-color="${night?'#536764':'#f4e8ce'}"/></linearGradient><clipPath id="perspective-boundary"><path d="${d}"/></clipPath><pattern id="papergrain" width="9" height="9" patternUnits="userSpaceOnUse"><circle cx="2" cy="3" r=".6" fill="#26392b" opacity=".12"/><circle cx="7" cy="7" r=".4" fill="#fff" opacity=".3"/></pattern></defs><rect width="1000" height="720" fill="url(#sky)"/><path d="M0 330Q180 230 350 310T680 270T1000 290V720H0Z" fill="${hill}" opacity=".75"/><path d="M0 390Q210 290 420 360T1000 340V720H0Z" fill="${night?'#2b4238':'#c1c7a2'}"/><path d="M0 470Q230 380 500 420T1000 440V720H0Z" fill="${night?'#293d35':'#d8d5b6'}"/>`;
if(night){html+=`<path d="M728 95a23 23 0 1 0 23 31 25 25 0 0 1-23-31Z" fill="#efdfaa"/>`;[[140,140],[310,90],[600,170],[820,190],[420,180],[890,120]].forEach(([x,y])=>html+=`<circle cx="${x}" cy="${y}" r="1.8" fill="#f0e6c6" opacity=".8"/>`)}else html+=`<circle cx="738" cy="145" r="38" fill="#eedaa0" opacity=".8"/>`;
const rear1=project({x:0,y:0}),rear2=project({x:1,y:0});html+=`<path d="M${rear1.x} ${rear1.y}L${rear2.x} ${rear2.y}V${rear2.y-64}L${rear1.x} ${rear1.y-64}Z" fill="${night?'#646c56':'#ded2b3'}" stroke="${night?'#7d8268':'#c3b99a'}"/><path d="M${rear1.x} ${rear1.y-64}L${rear2.x} ${rear2.y-64}" stroke="${night?'#85836a':'#e9ddbe'}" stroke-width="8"/>`;
html+=`<g transform="${mat}"><path d="${d}" transform="translate(0 14)" fill="#7e714e" opacity=".6"/><path d="${d}" fill="${MATERIALS[S.material].fill}" stroke="#6c7754" stroke-width="2"/><g clip-path="url(#perspective-boundary)">`;S.zones.forEach(z=>html+=`<path d="${pathFor(z.points,b)}" fill="url(#soil)" stroke="#7d684c"/>`);if(night)html+=`<path d="${d}" fill="#173032" opacity=".58"/>`;if(night&&S.lights)S.items.filter(i=>CATALOG[i.kind].type==='light').forEach(i=>{const p=xy(i,b);html+=`<circle cx="${p.x}" cy="${p.y}" r="${b.scale*4}" fill="url(#halo)" class="light-halo"/>`});html+='</g></g>';
[...S.items].sort((i,j)=>project(i).y-project(j).y).forEach(i=>{const p=project(i),cat=CATALOG[i.kind],scale=clamp(i.w*b.scale/72,.25,2.8),rotation=i.angle;html+=`<g transform="translate(${p.x} ${p.y})"><ellipse cy="8" rx="${scale*27}" ry="${scale*8}" fill="#273b2e" opacity=".19"/><g transform="scale(${scale})" opacity="${night?.82:1}"><g transform="skewX(${Math.sin(rotation*Math.PI/180)*8})">${sideIcon(i.kind,plantColor(),S.season==='winter'?'#d2cab7':S.season==='autumn'?'#c27340':'#b19ac3')}</g></g>${night&&S.lights&&cat.type==='light'?`<circle cx="0" cy="${i.kind==='light'?-scale*28:-scale*16}" r="${scale*20}" fill="url(#halo)" class="light-halo"/>`:''}</g>`});
html+=`<rect width="1000" height="720" fill="url(#papergrain)" pointer-events="none"/><text x="500" y="658" text-anchor="middle" fill="${night?'#e4debf':'#657451'}" font-family="Georgia" font-style="italic" font-size="16">${esc(S.name)} · ${S.season} ${night?'evening':'daylight'}</text>`;$('#perspective').innerHTML=html;$('#render-status').textContent='V'+S.version+' · '+S.items.length+' elements · updated';}
function download(content,name,type='text/plain'){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}
function exportProject(){const e=estimate();download(JSON.stringify({format:'Terra garden project',state:S,photo:photoData,estimate:{date:'2026-10-29',source:'Terra illustrative dataset; not live local prices',...e},phases:['Measure and observe site','Confirm layout, plant suitability and quotes','Resolve site conditions before ordering or digging'],unpriced:['Labour','Base preparation','Drainage','Demolition and disposal','Delivery and taxes','Permits'],professionalChecks:['Utilities and planned routes','Drainage and site survey','BBQ manufacturer installation conditions','Local permits and plant suitability']},null,2),'terra-garden-v'+S.version+'.json','application/json')}
function svgFile(id){const svg=$(id).cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.removeAttribute('role');svg.removeAttribute('aria-label');return new XMLSerializer().serializeToString(svg)}
function prompt(){return `Create a photorealistic garden visualization using the attached Terra top-down layout as a strict geometry reference.\nProject: ${S.name}.\nBoundary: ${S.shape}; site dimensions ${S.width} × ${S.depth} ft. Approximate area ${Math.round(estimate().area)} sq ft. Boundary normalized points (X right, Y down): ${JSON.stringify(S.points)}. ${S.shape==='curve'?'Rounded corners, rounding factor '+S.curve+'.':''}\nGround: ${MATERIALS[S.material].name}. Soil beds: ${JSON.stringify(S.zones.map(z=>({name:z.name,points:z.points})))}.\nObjects and locations (coordinates measured from upper-left in feet):\n${S.items.map(i=>`${CATALOG[i.kind].name}: X ${(i.x*S.width).toFixed(1)}, Y ${(i.y*S.depth).toFixed(1)}, footprint ${i.w} × ${i.h} ft, rotation ${i.angle}°`).join('\n')}\nSeason: ${S.season}. Time: ${S.night?'night':'warm daylight'}. Garden lights: ${S.lights?'on':'off'}.\nAtmosphere: tactile terracotta, olive and forest greens, warm Southern European courtyard. Real materials, believable scale, natural shadows. Preserve the exact number, placements and types of objects from the reference. Do not add pools, structures, paving areas or other items not in the plan. Keep site geometry; choose a useful eye-level perspective. Uploaded photo, if supplied separately, is a visual reference only and is not a measured survey. This is a conceptual image, not a construction drawing. Plants and seasonal appearance are visual approximations, not a suitability claim.`}
function routePage(){const route=location.hash.slice(1)||'home',name=['home','studio','pricing','visuals'].includes(route)?route:'home';$$('.page').forEach(p=>{p.hidden=p.id!==name;if(p.id===name){p.classList.remove('route-entry');requestAnimationFrame(()=>p.classList.add('route-entry'))}});$$('nav [data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===name);if(a.dataset.route===name)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title={home:'Terra — Your outside, imagined.',studio:'Garden studio — Terra',pricing:'The numbers — Terra',visuals:'See it bloom — Terra'}[name];if(name==='studio')renderAll(true);if(name==='pricing')renderPricing();if(name==='visuals'){renderAll();renderPerspective()}window.scrollTo({top:0,behavior:'instant'})}
window.addEventListener('hashchange',routePage);
$('#project-name').onchange=e=>change(()=>S.name=e.target.value.trim()||'My little outside');$('#next-step').onclick=()=>S.step===5?location.hash='visuals':setStep(S.step+1);$('#previous-step').onclick=()=>setStep(Math.max(0,S.step-1));$('#save').onclick=()=>save();$('#undo').onclick=()=>{if(!undoStack.length)return;redoStack.push(clone(S));S=undoStack.pop();selection=null;tool='select';draft=[];renderAll(true);scheduleSave();notify('Last change undone.')};$('#redo').onclick=()=>{if(!redoStack.length)return;undoStack.push(clone(S));S=redoStack.pop();selection=null;renderAll(true);scheduleSave();notify('Change restored.')};$('#day').onclick=()=>change(()=>S.night=false);$('#night').onclick=()=>change(()=>S.night=true);$('#lights').onchange=e=>change(()=>S.lights=e.target.checked);$('#season').onchange=e=>change(()=>S.season=e.target.value,{controls:true});$('#plan-view').onclick=()=>{photoMode=false;renderCanvas()};$('#photo-view').onclick=()=>{if(!photoData){$('#photo-input').click();return}photoMode=true;renderCanvas()};$('#fit').onclick=()=>{selection=null;renderAll();notify('Garden fitted to the canvas.')};$('#target-budget').oninput=e=>{S.target=+e.target.value;$('#target-label').textContent=money(S.target);scheduleSave()};$('#target-budget').onchange=()=>renderPricing();$('#reserve').onchange=e=>change(()=>S.reserve=+e.target.value);$('#export-plan').onclick=exportProject;$('#render-time').onchange=e=>change(()=>S.night=e.target.value==='night');$('#render-season').onchange=e=>change(()=>S.season=e.target.value);$('#render-lights').onchange=e=>change(()=>S.lights=e.target.checked);$('#refresh-render').onclick=()=>{renderPerspective();$('#render-status').textContent='Refreshed from your current plan · V'+S.version};$('#download-render').onclick=()=>download(svgFile('#perspective'),'terra-perspective-v'+S.version+'.svg','image/svg+xml');$('#download-layout').onclick=()=>{selection=null;const old=photoMode;photoMode=false;renderCanvas();download(svgFile('#garden'),'terra-layout-v'+S.version+'.svg','image/svg+xml');photoMode=old;renderCanvas()};$('#copy-prompt').onclick=async()=>{const text=prompt();try{await navigator.clipboard.writeText(text);$('#prompt-status').textContent='Copied. Attach the layout reference to your image model.'}catch(e){$('#prompt-text').value=text;$('#prompt-dialog').showModal()}};
$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#existing-entry').onclick=()=>{location.hash='studio';setStep(0);$('#photo-input').click()};$('#open-project').onclick=()=>{location.hash='studio';notify('Your current project is open. Changes auto-save on this device.')};$('#blank-entry').onclick=()=>{$('#welcome').close();location.hash='studio'};$('#photo-entry').onclick=()=>{$('#welcome').close();location.hash='studio';setStep(0);$('#photo-input').click()};
$('#photo-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){notify('Choose a JPG, PNG or WebP image under 15 MB.');e.target.value='';return}try{const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();photoData=canvas.toDataURL('image/jpeg',.85);photoMode=true;location.hash='studio';renderAll(true);await save(false);notify('Photo added privately. Mark soil in step 02. Enter measured dimensions separately.')}catch(err){notify('This image could not be opened. Try a different JPG or PNG.')}e.target.value=''};
$('#project-input').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>18*1024*1024){notify('Project file is too large.');return}try{const data=JSON.parse(await f.text());if(!validState(data.state))throw Error('format');const photo=data.photo;if(photo&&!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(photo))throw Error('photo');checkpoint();S=clone(data.state);photoData=photo||null;photoMode=false;selection=null;tool='select';draft=[];renderAll(true);save();notify('Editable project restored from your file.')}catch(err){notify('This is not a valid Terra project. Your current garden is unchanged.')}e.target.value=''};
